const script = $input.item.json.body.script;
const title = $input.item.json.body.title;
const userId = $input.item.json.body.user_id;
const dbVideoId = $input.item.json.body.video_id;

const timestamp = Date.now();
const safeTitle = title.toLowerCase().replace(/[^a-z0-9]/g, '_');
const videoId = `${safeTitle}_${timestamp}`;
const workDir = `/home/node/.n8n-files/render_${videoId}`;

return {
  json: {
    script,
    title,
    userId,
    videoId,
    dbVideoId,
    workDir,
    scenes: script.scenes,
    sceneCount: script.scenes.length
  }
};

const scenes = $('Process Input').item.json.scenes;
const workDir = $('Process Input').item.json.workDir;
const userId = $('Process Input').item.json.userId;
const videoId = $('Process Input').item.json.videoId;
const outputVideo = `${workDir}/final_video.mp4`;
const scriptPath = `${workDir}/render.sh`;

// Construir script bash
let bash = '#!/bin/sh\nset -e\n\n';
bash += `echo "=== Starting render ==="\n\n`;

// Downloads
for (let i = 0; i < scenes.length; i++) {
  const scene = scenes[i];
  bash += `echo "Downloading scene ${i}..."\n`;
  bash += `wget -q -O "${workDir}/image_${i}.png" "${scene.imageUrl}"\n`;
  bash += `wget -q -O "${workDir}/audio_${i}.wav" "${scene.audioUrl}"\n`;
  bash += `ls -lah "${workDir}/image_${i}.png" "${workDir}/audio_${i}.wav"\n`;
}

bash += `\necho "=== Rendering scenes ==="\n`;

// Render cada cena
for (let i = 0; i < scenes.length; i++) {
  const scene = scenes[i];
  const duration = scene.durationInSeconds;
  const frames = Math.ceil(duration * 30);
  const zoomSpeed = (0.2 / duration).toFixed(8);

  bash += `echo "Rendering scene ${i}..."\n`;
  bash += `ffmpeg -y -loop 1 -i "${workDir}/image_${i}.png" -i "${workDir}/audio_${i}.wav" -vf "scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,zoompan=z='min(1+${zoomSpeed}*on/${frames},1.2)':d=${frames}:x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':s=1080x1920:fps=30" -c:v libx264 -preset fast -c:a aac -shortest -pix_fmt yuv420p "${workDir}/scene_${i}.mp4"\n`;
  bash += `echo "Scene ${i} done"\n\n`;
}

// Concat file
bash += `> "${workDir}/concat.txt"\n`;
for (let i = 0; i < scenes.length; i++) {
  bash += `echo "file '${workDir}/scene_${i}.mp4'" >> "${workDir}/concat.txt"\n`;
}

// Concatenar
bash += `echo "=== Concatenating ==="\n`;
bash += `ffmpeg -y -f concat -safe 0 -i "${workDir}/concat.txt" -c copy "${outputVideo}"\n`;
bash += `echo "Done: $(ls -lah ${outputVideo})"\n`;

// Converter para base64 (sem quebras de linha)
const scriptBase64 = Buffer.from(bash).toString('base64').replace(/\n/g, '');

return [{ json: { scriptBase64, scriptPath, outputVideo, workDir, userId, videoId } }];

const outputVideo = $('Build Render Script').item.json.outputVideo;
const userId = $('Build Render Script').item.json.userId;
const videoId = $('Build Render Script').item.json.videoId;
const workDir = $('Build Render Script').item.json.workDir;

return [{ json: { outputVideo, userId, videoId, workDir } }];

const userId = $('Prepare Upload').item.json.userId;
const videoId = $('Prepare Upload').item.json.videoId;
const title = $('Process Input').item.json.title;

const publicUrl = `https://qgbxduvipeadycxremqa.supabase.co/storage/v1/object/public/rendered-videos/${userId}/${videoId}.mp4`;

return [{ json: { videoUrl: publicUrl, userId, title } }];
